"""Local review index for the full extension and latest matched views."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];dest=ROOT/'recon/v45'
geometry=json.loads((dest/'validation.json').read_text());checks=json.loads((dest/'route-checks.json').read_text());preserved=json.loads((dest/'v40-preservation.json').read_text());views=json.loads((dest/'review-views.json').read_text())['views']
rows=[]
for label in dict.fromkeys(v['view'] for v in views):
 rows.append('<h2>'+html.escape(label)+'</h2><div class="pair">'+''.join('<figure><img src="'+v['image']+'"><figcaption>'+v['stage']+'</figcaption></figure>' for v in views if v['view']==label)+'</div>')
page='''<!doctype html><meta charset="utf-8"><title>Melton / station / Holmdale extension — v45 review</title><style>body{background:#18212b;color:#edf0f4;font:17px system-ui;margin:30px;max-width:1500px}a{color:#9cd6ff}.pair{display:flex;gap:12px}figure{margin:0;width:50%}img{width:100%}pre{white-space:pre-wrap}</style><h1>Melton / station / Holmdale — v45 working copy</h1><p>Google top-down alignment is still unverified. The model uses an OSM-derived route frame and user-supplied house/road references; estimated dimensions and gameplay boundaries are labelled in the notes. The goal is unfinished and the requested final Git push has not happened.</p><p><a href="../v41/index.html">Route before/after</a> · <a href="../v42/index.html">Midland exterior</a> · <a href="../v44/index.html">Number 29 details</a></p><p>Latest pass adds a mapped car park and rail corridor, lowers the rail bed beneath the retained platform, replaces the narrow platform walls with a distant low plinth/metal perimeter, adds a parallel access ramp, and widens Holmdale’s end with the photo-observed brick/timber closure. The exact ramp, turning outline, heights and perimeter remain estimates. BO3 unchanged.</p><p>Map data © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>, ODbL. Station references: <a href="https://www.nationalrail.co.uk/stations/syston/">National Rail</a>, <a href="https://www.geograph.org.uk/photo/3779706">Nigel Thompson, 2012, CC BY-SA 2.0</a>, <a href="https://www.geograph.org.uk/photo/8028555">David Howard, 2025, CC BY-SA 2.0</a>. User Google reference imagery remains local and is not embedded or redistributed here.</p>'''
page+=''.join(rows)+'<h2>Verification</h2><pre>'+html.escape(json.dumps({'geometry':geometry,'routes':{k:checks[k] for k in ('clearance_rays','floor_samples','blocked_count','unsupported_count','floor_height_range','sampled_routes','limits')},'v40_preservation':preserved},indent=2))+'</pre>'
(dest/'index.html').write_text(page,encoding='utf-8');print(dest/'index.html')
